const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=value=>Number.isSafeInteger(value)?value.toLocaleString('zh-CN'):'—';
const date=value=>value&&Number.isFinite(Date.parse(value))?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'—';
const labels={active:'发放中',exhausted:'已结束',available:'未使用',redeemed:'已兑换',expired:'已过期',revoked:'已作废'};
const validList=value=>value&&typeof value.enabled==='boolean'&&Array.isArray(value.items)&&Number.isSafeInteger(value.total)&&Number.isSafeInteger(value.page)&&value.metrics&&['issued','redeemed','available','redeemedCredits'].every(key=>Number.isSafeInteger(value.metrics[key]));
export function mountAdminCreditCodes({container,data,actorId,request,isCurrent,toast,openDialog,closeDialog}){
 const doc=container.ownerDocument,win=doc.defaultView,$=selector=>container.querySelector(selector),storageKey='paperknow-credit-code-command:'+actorId;
 let disposed=false,busy=false,listing=data,detail=null,listTicket=0,detailTicket=0,pending=null;
 const query={page:1,pageSize:10,q:'',status:''},live=()=>!disposed&&container.isConnected&&isCurrent();
 if(!doc.querySelector('link[data-admin-credit-codes-style]')){const style=doc.createElement('link');style.rel='stylesheet';style.href='/admin-credit-codes.css';style.dataset.adminCreditCodesStyle='';doc.head.append(style);}
 if(!validList(data))throw Error('兑换码管理数据不完整，请刷新后重试');
 container.innerHTML=`<div class="code-admin-metrics" data-code-admin-metrics></div><section class="panel code-admin-create"><header><div><span class="code-admin-eyebrow">积分活动与发放</span><h2>生成积分兑换码</h2><p>按活动批次管理面额、有效期与使用情况。生成成功后自动下载 CSV，也可在记录中重新导出。</p></div><span class="badge blue">单码单次兑换</span></header><form data-code-create-form><div class="code-admin-fields"><label>批次名称<input name="name" maxlength="80" placeholder="例如：新用户体验活动" required></label><label>每码积分<input name="creditAmount" type="number" min="1" max="1000000" step="1" value="1000" required></label><label>生成数量<input name="quantity" type="number" min="1" max="200" step="1" value="10" required></label><label>兑换截止日期<input name="expires" type="date" value="${new Date(Date.now()+8*3600000+90*86400000).toISOString().slice(0,10)}" required><small>当日 23:59:59 截止（北京时间）</small></label></div><div class="code-admin-create-footer"><p data-code-create-summary></p><button type="submit" class="button primary">生成并下载兑换码</button></div><p role="status" aria-live="polite" data-code-create-status></p></form></section><section class="panel code-admin-list"><header><div><h2>兑换码批次</h2><p>已使用的兑换码不可再次兑换，作废批次不会撤回已到账积分。</p></div></header><form data-code-filter><input name="q" type="search" maxlength="80" placeholder="搜索批次名称" aria-label="搜索批次名称"><select name="status" aria-label="批次状态"><option value="">全部状态</option><option value="active">发放中</option><option value="expired">已过期</option><option value="exhausted">已结束</option><option value="revoked">已作废</option></select><button class="button" type="submit">查询</button></form><div data-code-batch-rows></div><div class="code-admin-pagination"><button type="button" class="button" data-code-batch-page="previous">上一页</button><span data-code-batch-page-label></span><button type="button" class="button" data-code-batch-page="next">下一页</button></div><p role="status" data-code-admin-message></p></section><section class="panel code-admin-detail" data-code-admin-detail hidden></section>`;
 const status=(text,error=false)=>{if(live()){const node=$('[data-code-create-status]');node.textContent=text;node.classList.toggle('is-error',error);}};
 function controls(){if(!live())return;for(const input of $('[data-code-create-form]').elements)input.disabled=busy||!listing.enabled||Boolean(pending&&input.type!=='submit');$('[data-code-create-form] [type=submit]').textContent=busy?'正在处理…':pending?'核对上次生成并下载':'生成并下载兑换码';container.querySelectorAll('[data-code-batch-export],[data-code-batch-revoke],[data-code-item-revoke]').forEach(button=>button.disabled=busy||button.dataset.unavailable==='true');}
 function summary(){const form=$('[data-code-create-form]'),quantity=Number(form.elements.quantity.value),amount=Number(form.elements.creditAmount.value),total=quantity*amount;$('[data-code-create-summary]').textContent=Number.isSafeInteger(total)&&quantity>0&&amount>0?`将生成 ${number(quantity)} 个兑换码，每码 ${number(amount)} 积分，总额 ${number(total)} 积分。`:'请填写积分面额和生成数量。';}
 function renderList(){if(!live())return;const m=listing.metrics;$('[data-code-admin-metrics]').innerHTML=[['已生成',m.issued,'个兑换码'],['可兑换',m.available,'个未使用'],['已兑换',m.redeemed,'个已使用'],['已到账积分',m.redeemedCredits,'积分 · 不计入支付收入']].map(([title,value,note])=>`<article><span>${title}</span><strong>${number(value)}</strong><small>${note}</small></article>`).join('');$('[data-code-batch-rows]').innerHTML=listing.items.length?`<div class="code-admin-table-scroll"><table><thead><tr><th>批次 / 面额</th><th>数量 / 使用</th><th>兑换截止</th><th>状态</th><th>操作</th></tr></thead><tbody>${listing.items.map(row=>`<tr><td><strong>${esc(row.name)}</strong><small>每码 ${number(row.creditAmount)} 积分</small></td><td><strong>${number(row.quantity)} 个</strong><small>已兑换 ${number(row.counts.redeemed)} · 可兑换 ${number(row.counts.available)}</small></td><td>${date(row.expiresAt)}</td><td><span class="badge ${row.status==='active'?'green':''}">${labels[row.status]||'状态待核对'}</span></td><td><div class="row-actions"><button class="text-button" type="button" data-code-detail="${esc(row.id)}">查看兑换码</button><button class="text-button" type="button" data-code-batch-export="${esc(row.id)}" data-unavailable="${!listing.enabled||!row.counts.available}">导出未使用</button><button class="text-button cancel" type="button" data-code-batch-revoke="${esc(row.id)}" data-unavailable="${row.status!=='active'||!row.counts.available}">作废批次</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="code-admin-empty">暂无符合条件的兑换码批次。</div>';$('[data-code-batch-page-label]').textContent=query.page+' / '+Math.max(1,Math.ceil(listing.total/query.pageSize))+' · 共 '+number(listing.total)+' 批';$('[data-code-batch-page="previous"]').disabled=query.page<=1;$('[data-code-batch-page="next"]').disabled=query.page*query.pageSize>=listing.total;controls();}
 async function loadList(){const ticket=++listTicket;try{const value=await request('/admin/credit-codes?'+new URLSearchParams({...query,page:String(query.page),pageSize:String(query.pageSize)}));if(!live()||ticket!==listTicket)return;if(!validList(value))throw Error('兑换码列表不完整，请刷新后重试');const last=Math.max(1,Math.ceil(value.total/query.pageSize));if(query.page>last){query.page=last;return loadList();}listing=value;renderList();$('[data-code-admin-message]').textContent='';}catch(error){if(live()&&ticket===listTicket)$('[data-code-admin-message]').textContent=error.message;}}
 function renderDetail(){if(!live()||!detail)return;const area=$('[data-code-admin-detail]');area.hidden=false;area.innerHTML=`<header><div><h2>${esc(detail.batch.name)}</h2><p>每码 ${number(detail.batch.creditAmount)} 积分 · 截止 ${date(detail.batch.expiresAt)}</p></div><button type="button" class="button" data-code-detail-close>收起明细</button></header><div class="code-admin-table-scroll"><table><thead><tr><th>兑换码</th><th>状态</th><th>兑换账户</th><th>兑换时间</th><th>操作</th></tr></thead><tbody>${detail.items.map(row=>`<tr><td><code>${esc(row.hint)}</code></td><td><span class="badge ${row.status==='redeemed'?'green':''}">${labels[row.status]||'状态待核对'}</span></td><td>${row.redeemedBy?esc(row.redeemedBy.name)+'<small>'+esc(row.redeemedBy.id)+'</small>':'—'}</td><td>${date(row.redeemedAt)}</td><td><button class="text-button cancel" type="button" data-code-item-revoke="${esc(row.id)}" data-unavailable="${row.status!=='available'}">作废</button></td></tr>`).join('')}</tbody></table></div><div class="code-admin-pagination"><button type="button" class="button" data-code-detail-page="previous" ${detail.page<=1?'disabled':''}>上一页</button><span>${detail.page} / ${Math.max(1,Math.ceil(detail.total/detail.pageSize))} · 共 ${number(detail.total)} 个</span><button type="button" class="button" data-code-detail-page="next" ${detail.page*detail.pageSize>=detail.total?'disabled':''}>下一页</button></div>`;controls();}
 async function loadDetail(id,page=1){const ticket=++detailTicket;try{const value=await request('/admin/credit-codes/'+encodeURIComponent(id)+'?page='+page+'&pageSize=20');if(!live()||ticket!==detailTicket)return;if(!value.batch?.id||!Array.isArray(value.items))throw Error('兑换码明细不完整，请重试');detail=value;renderDetail();}catch(error){if(live())toast(error.message);}}
 async function download(id){const value=await request('/admin/credit-codes/'+encodeURIComponent(id)+'/export',{status:'available'});const account=await request('/auth/me');if(!live())return;if(account.user?.id!==actorId||account.user.role!=='admin')throw Error('管理账户已变化，未下载兑换码，请重新登录后操作');if(typeof value.csv!=='string'||!value.csv.startsWith('\uFEFF')||!Number.isSafeInteger(value.rows)||value.rows<1||typeof value.filename!=='string'||!/^[^/\\]+\.csv$/.test(value.filename))throw Error('兑换码文件未准备完成，请重试');const url=win.URL.createObjectURL(new win.Blob([value.csv],{type:'text/csv;charset=utf-8'})),link=doc.createElement('a');link.href=url;link.download=value.filename;doc.body.append(link);try{link.click();}finally{link.remove();win.setTimeout(()=>win.URL.revokeObjectURL(url),10000);}return value.rows;}
 function cache(value){try{if(value)win.sessionStorage.setItem(storageKey,JSON.stringify(value));else win.sessionStorage.removeItem(storageKey);}catch{if(value)throw Error('暂时无法保留本次操作标识，请检查浏览器存储后重试');}}
 async function create(event){event.preventDefault();if(busy||!live()||!listing.enabled)return;let input;try{const form=$('[data-code-create-form]');input=pending?.input||{name:form.elements.name.value.trim(),creditAmount:Number(form.elements.creditAmount.value),quantity:Number(form.elements.quantity.value),expiresAt:new Date(form.elements.expires.value+'T23:59:59+08:00').toISOString()};if(!input.name||!Number.isSafeInteger(input.creditAmount)||input.creditAmount<1||input.creditAmount>1000000||!Number.isSafeInteger(input.quantity)||input.quantity<1||input.quantity>200||input.quantity*input.creditAmount>10000000)throw Error('请填写批次名称，单批 1～200 个，总额不超过 10,000,000 积分');if(!pending){const next={commandId:win.crypto.randomUUID(),input};cache(next);pending=next;}busy=true;controls();status('正在生成并保存兑换码…');const value=await request('/admin/credit-codes',{commandId:pending.commandId,...pending.input});if(!live())return;if(!value.batch?.id||typeof value.created!=='boolean')throw Error('生成结果未确认，请原样重试核对');pending=null;cache(null);status((value.created?'已生成':'已核对原有')+' '+number(value.batch.quantity)+' 个兑换码，正在准备下载…');try{const rows=await download(value.batch.id);if(live())status('批次已保存，已发起 '+number(rows)+' 个未使用兑换码的 CSV 下载，请确认文件已保存。');}catch(error){if(live())status('批次已保存，CSV 导出未完成：'+error.message+'。可在下方重新导出。',true);}query.page=1;query.q='';query.status='';await loadList();}catch(error){if(live()){if(error.status>=400&&error.status<500){pending=null;cache(null);}status(error.message+(pending?'；请求结果尚未确认，可点击“核对上次生成并下载”，不会重复生成。':''),true);}}finally{busy=false;controls();}}
 async function exportBatch(id){if(busy||!live())return;busy=true;controls();try{const rows=await download(id);if(live())toast('已发起 '+number(rows)+' 个兑换码的 CSV 下载，请确认文件已保存。');}catch(error){if(live())toast(error.message);}finally{busy=false;controls();}}
 function confirmRevoke(kind,id){if(busy||!live())return;const row=kind==='batch'?listing.items.find(row=>row.id===id):detail?.items.find(row=>row.id===id);if(!row)return;openDialog(kind==='batch'?'作废兑换码批次':'作废此兑换码',`<p class="dialog-copy">${kind==='batch'?'将停用本批次剩余 '+number(row.counts.available)+' 个未使用兑换码。':'作废后此码将不能兑换。'}已到账积分不受影响。</p><form data-code-revoke-form><label class="code-admin-revoke-label">作废原因<textarea name="reason" maxlength="300" rows="3" required placeholder="填写作废原因，便于后续追溯"></textarea></label><p role="status" data-code-revoke-error></p><div class="dialog-actions"><button type="button" class="button" data-dialog-close>取消</button><button type="submit" class="button danger-solid">确认作废</button></div></form>`);const form=doc.querySelector('[data-code-revoke-form]'),commandId=win.crypto.randomUUID();form.addEventListener('submit',async event=>{event.preventDefault();if(busy||!live()||!form.isConnected)return;const reason=form.elements.reason.value.trim();if(!reason)return;busy=true;controls();for(const field of form.elements)field.disabled=true;try{await request('/admin/'+(kind==='batch'?'credit-codes/':'credit-code-items/')+encodeURIComponent(id)+'/revoke',{commandId,version:row.version,reason});if(!live())return;if(form.isConnected)closeDialog();toast('兑换码已作废。');await loadList();if(detail)await loadDetail(detail.batch.id,detail.page);}catch(error){if(live()&&form.isConnected)form.querySelector('[data-code-revoke-error]').textContent=error.message;}finally{busy=false;controls();if(form.isConnected)for(const field of form.elements)field.disabled=false;}});}
 $('[data-code-create-form]').addEventListener('submit',event=>void create(event));$('[data-code-create-form]').addEventListener('input',summary);
 $('[data-code-filter]').addEventListener('submit',event=>{event.preventDefault();if(busy)return;query.q=event.target.elements.q.value.trim();query.status=event.target.elements.status.value;query.page=1;void loadList();});
 const click=event=>{const button=event.target.closest('button');if(!button||!container.contains(button)||button.disabled||busy)return;if(button.dataset.codeDetail)void loadDetail(button.dataset.codeDetail);if(button.dataset.codeBatchExport)void exportBatch(button.dataset.codeBatchExport);if(button.dataset.codeBatchRevoke)confirmRevoke('batch',button.dataset.codeBatchRevoke);if(button.dataset.codeItemRevoke)confirmRevoke('code',button.dataset.codeItemRevoke);if(button.dataset.codeBatchPage){query.page+=button.dataset.codeBatchPage==='next'?1:-1;void loadList();}if(button.dataset.codeDetailPage&&detail)void loadDetail(detail.batch.id,detail.page+(button.dataset.codeDetailPage==='next'?1:-1));if(button.hasAttribute('data-code-detail-close')){detailTicket++;detail=null;$('[data-code-admin-detail]').hidden=true;}};container.addEventListener('click',click);
 try{const saved=JSON.parse(win.sessionStorage.getItem(storageKey)||'null');if(saved?.commandId&&saved.input?.name&&Number.isSafeInteger(saved.input.creditAmount)&&Number.isSafeInteger(saved.input.quantity)&&Number.isFinite(Date.parse(saved.input.expiresAt))){pending=saved;const form=$('[data-code-create-form]');for(const key of ['name','creditAmount','quantity'])form.elements[key].value=saved.input[key];form.elements.expires.value=new Date(Date.parse(saved.input.expiresAt)+8*3600000).toISOString().slice(0,10);status('已恢复未确认的生成请求，请原样核对，不会重复生成。');}}catch{status('未读取到可恢复的生成请求，请核对现有批次后操作。',true);}
 renderList();summary();if(!listing.enabled)status(listing.reason||'兑换码生成暂不可用，请核对服务器设置。',true);controls();
 return{hasWork:()=>busy,dispose(){disposed=true;listTicket++;detailTicket++;container.removeEventListener('click',click);}};
}
